/**
 * Generated by `createservice subscription.CancelSubscriptionRenewalService --type mutations`
 */
const uniq = require('lodash/uniq')

const { throwAuthenticationError } = require('@open-condo/keystone/apolloErrorFormatter')
const { find } = require('@open-condo/keystone/schema')

const { checkPermissionsInEmployedOrRelatedOrganizations } = require('@condo/domains/organization/utils/accessSchema')
const { STAFF } = require('@condo/domains/user/constants/common')


async function canCancelSubscriptionRenewal ({ authentication: { item: user }, args, context }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false
    if (user.isAdmin || user.isSupport) return true

    if (user.type !== STAFF) return false

    const subscriptionContextIds = uniq((args.data?.subscriptionContexts || []).map(({ id }) => id).filter(Boolean))
    if (subscriptionContextIds.length === 0) return false

    const subscriptionContexts = await find('SubscriptionContext', { id_in: subscriptionContextIds, deletedAt: null })
    if (subscriptionContexts.length !== subscriptionContextIds.length) return false

    const organizationIds = uniq(subscriptionContexts.map(subscriptionContext => subscriptionContext.organization).filter(Boolean))
    if (organizationIds.length === 0) return false

    return await checkPermissionsInEmployedOrRelatedOrganizations(context, user, organizationIds, 'canManageSubscriptions')
}

/*
  Rules are logical functions that used for list access, and may return a boolean (meaning
  all or no items are available) or a set of filters that limit the available items.
*/
module.exports = {
    canCancelSubscriptionRenewal,
}
